var S;

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  S = max(width, height) * 0.04;
  // noLoop() removed for animation
  noFill();
  strokeWeight(3);
}

function draw() {
	background(255);

  for (let i = 0; i < width / S; i++) {
    for (let j = 0; j < height / S; j++) {
var sd = floor(random(2));
var x = i * S;
var y = j * S;

      push();
      translate(x, y);

      switch (sd) {
        case 0:
          line(0, S / 2, S, S / 2);
          break;
        case 1:
          beginShape();
          for (let x = 0; x < S+1; x++) {
            var y = S / 2 * sin(x * 360 / S) + S / 2;
            vertex(x, y);
          }
          endShape();
          break;
      }

      pop();
    }
  }
}
